void sleepScreen(void) {
    u8g2.setPowerSave(0);
    u8g2.clearBuffer();
    u8g2.setFontMode(1);
    u8g2.setBitmapMode(1);
    u8g2.drawXBMP(57, 24, 15, 16, sleepBits);
    u8g2.setDrawColor(2);
    u8g2.sendBuffer();
    delay(1000);
}

int backDelay = 100;
int backTime = 0;

bool buzzerOn = false;
bool lastHeld = false;
unsigned long buzzerTimer = 0;

const unsigned long BEEP_TIME = 50;
const unsigned long scrollDelay = 180;
const unsigned long BEEP_DELAY = scrollDelay - BEEP_TIME;

void updateBuzzer()
{
    bool held = anyButtonHold();

    // Detect button press
    if (held && !lastHeld && !buzzerOn)
    {
        playBuzzer(true);
        buzzerOn = true;
        buzzerTimer = millis();
    }

    if (buzzerOn)
    {
        // Finish current beep
        if (millis() - buzzerTimer >= BEEP_TIME)
        {
            playBuzzer(false);
            buzzerOn = false;
            buzzerTimer = millis();
        }
    }
    else if (held)
    {
        // Start another beep after the delay
        if (millis() - buzzerTimer >= BEEP_DELAY)
        {
            playBuzzer(true);
            buzzerOn = true;
            buzzerTimer = millis();
        }
    }

    lastHeld = held;
}

void backtoMenu(void){
    currentScene = 0;
}

void loop(void)
{
    updateBuzzer();
    resetButtonStates();

    if(anyButtonHold()){
        afkTime = 0; 
    } else {
        afkTime += 1; 
    }

    if(afkTime >= maxAfkTime){
        sleepScreen();
        btStop();
        esp_sleep_enable_ext0_wakeup((gpio_num_t)33, 0);
        u8g2.setPowerSave(1);
        delay(50);
        while (digitalRead(leftButton) == LOW) {
            delay(10);
        }
        wokefromSleep = 1;
        esp_deep_sleep_start();
        return;
    }

    switch (currentScene)
    {
        case -1:
        faces();
        if (selectButtonTap())
        {
            currentScene = 0; // if the select button is pressed, go back to the main menu
        }
        break;
        case 0:
            static long lastScroll = millis();
            mainMenu(); // display the main menu
            if (upButtonHold() && millis() - lastScroll > scrollDelay)
            {
                previousItem(); // if the previous button is pressed, go to the previous item
                lastScroll = millis();
            }
            if (selectButtonTap())
            {
                if(currentItemIndex == 0){
                    currentScene = -1;
                    return;
                }
                currentScene = currentItemIndex; // set the current scene to the selected item index
            }
            if (downButtonHold() && millis() - lastScroll > scrollDelay)
            {
                nextItem(); // if the next button is pressed, go to the next item
                lastScroll = millis();
            }
        break;
            
        case 1:
            compass(!leftButtonHold() && !rightButtonHold() ? 0 : (!leftButtonHold() && rightButtonHold() ? -1 : 1), downButtonTap()); // display the compass

            if (selectButtonTap())
            {
                currentScene = 0; // if the select button is pressed, go back to the main menu
            }
        break;
    
        case 2:
            if (rightButtonHold())
            {
                backTime += 1;
                if(backTime > backDelay){

                    backTime = 0;
                    currentScene = 0;        // if the select button is pressed, go back to the main menu
                    return;
                }
            }else{
                backTime = 0;
            }
            ButtonTest(backTime, backDelay);
        break;;
    
        case 3:
            PC_Control();
            if (selectButtonTap())
            {
                currentScene = 0;        // if the select button is pressed, go back to the main menu
            }
        break;

        case 4:
            settingsPage();
            if (selectButtonTap())
            {
                currentScene = 0;        // if the select button is pressed, go back to the main menu
            }
        break;

        case 5:
            clockFunc(0);
            if (selectButtonTap())
            {   
                if(clockMode != NONE){
                    clockMode = NONE;
                    return;
                }
                clockFunc(1);
                gotInfo = 0;
                currentScene = 0;        // if the select button is pressed, go back to the main menu
            }
        break;

        case 6:
            gamesMenu(0);
            // if(selectButtonTap()){
            //     gamesMenu(1);
            //     currentScene = 0;
            // }
        break;

        case 7:
            version();
            if(selectButtonTap()){
                currentScene = 0;
            }
        break;
        case 8:
            drawTextScreen();
            if(selectButtonTap()){
                currentScene = 0;
            }
        break;
    }
}